arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'))
for u in d['members']:
    flags=[]
    if u.get('is_owner'): flags.append('OWNER')
    if u.get('is_admin'): flags.append('admin')
    if u.get('deleted'): flags.append('deleted')
    print(u['id'], '|', ','.join(flags), '|', u['profile'].get('real_name'))
"

